rw(p,'        suspend fun finish(message: String, didAct: Boolean): Result {\n            if (didAct && message.isNotBlank()','        suspend fun finish(message: String, didAct: Boolean): Result {\n            service?.hideAgentCursor()\n            if (didAct && message.isNotBlank()')
rw(p,'            if (cancelled()) return Result("Tarefa interrompida por você.", acted)\n','            if (cancelled()) { service?.hideAgentCursor(); return Result("Tarefa interrompida por você.", acted) }\n')
